/* Parameterized messages keep client identities and stored values unchanged. */
window.LuxiaPolish = (() => {
  const normalize = value => value.replace(/\s+/g, ' ').trim();
  const copy = new Map(Object.entries(window.LUXIA_PL).map(([key,value]) => [normalize(key),value]));
  const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const names = ['styczeń','luty','marzec','kwiecień','maj','czerwiec','lipiec','sierpień','wrzesień','październik','listopad','grudzień'];
  const genitive = ['stycznia','lutego','marca','kwietnia','maja','czerwca','lipca','sierpnia','września','października','listopada','grudnia'];
  const weekdays = {Monday:'poniedziałek',Tuesday:'wtorek',Wednesday:'środa',Thursday:'czwartek',Friday:'piątek',Saturday:'sobota',Sunday:'niedziela'};
  const countries = {'Belgium':'Belgia','Netherlands':'Holandia','Poland':'Polska','France':'Francja','Germany':'Niemcy','Luxembourg':'Luksemburg','United Kingdom':'Wielka Brytania','Ireland':'Irlandia','Spain':'Hiszpania','Portugal':'Portugalia','Italy':'Włochy','Switzerland':'Szwajcaria','Austria':'Austria','Denmark':'Dania','Sweden':'Szwecja','Norway':'Norwegia','Finland':'Finlandia','Iceland':'Islandia','Greece':'Grecja','Cyprus':'Cypr','Malta':'Malta','Czechia':'Czechy','Slovakia':'Słowacja','Hungary':'Węgry','Romania':'Rumunia','Bulgaria':'Bułgaria','Croatia':'Chorwacja','Slovenia':'Słowenia','Serbia':'Serbia','Bosnia & Herzegovina':'Bośnia i Hercegowina','Montenegro':'Czarnogóra','North Macedonia':'Macedonia Północna','Albania':'Albania','Lithuania':'Litwa','Latvia':'Łotwa','Estonia':'Estonia','Ukraine':'Ukraina','Moldova':'Mołdawia','Türkiye':'Turcja','United States / Canada':'Stany Zjednoczone / Kanada','Mexico':'Meksyk','Brazil':'Brazylia','Argentina':'Argentyna','Australia':'Australia','New Zealand':'Nowa Zelandia','Japan':'Japonia','South Korea':'Korea Południowa','China':'Chiny','India':'Indie','United Arab Emirates':'Zjednoczone Emiraty Arabskie','Israel':'Izrael','South Africa':'Republika Południowej Afryki','Morocco':'Maroko'};
  function dateText(value) {
    let result = value.replace(new RegExp(`\\b(\\d{1,2}) (${months.join('|')})\\b`, 'g'), (_,day,month)=>`${day} ${genitive[months.indexOf(month)]}`);
    result = result.replace(new RegExp(`\\b(${months.join('|')})\\b`, 'g'), month=>names[months.indexOf(month)]);
    return result.replace(/\b(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)\b/g,day=>weekdays[day]).replace(/\bat\b/g,'o');
  }
  function slotText(value) { return dateText(value).replace('20-minute consultation','konsultacja 20-minutowa').replace('1-hour session','sesja 1-godzinna'); }
  function translate(source) {
    const key = normalize(source);
    if (copy.has(key)) return source.replace(/\S[\s\S]*\S|\S/, () => copy.get(key));
    const country = key.match(/^(\S+)\s+(.+?)\s+\((\+\d+)\)$/u);
    if (country && countries[country[2]]) return `${country[1]} ${countries[country[2]]} (${country[3]})`;
    const patterns = [
      [/^(\d+) available times? on (.+)$/,(_,n,date)=>`Dostępne terminy na ${dateText(date)}: ${n}`],
      [/^(\d+) available times? in (.+)\.$/,(_,n,date)=>`Dostępne terminy (${dateText(date)}): ${n}.`],
      [/^No available times have been published for (.+) yet\.$/,(_,date)=>`Nie opublikowano jeszcze wolnych terminów (${dateText(date)}).`],
      [/^(.+) — available hours$/,(_,date)=>`${dateText(date)} — dostępne godziny`],
      [/^Choose (.+)$/,(_,slot)=>`Wybierz ${slotText(slot)}`],
      [/^Your verified account details will be used: (.+)\.$/,(_,identity)=>`Zostaną użyte zweryfikowane dane Twojego konta: ${identity}.`],
      [/^Your account name and email will be used automatically \((.+)\)\. Please add a phone number for this message\.$/,(_,identity)=>`Imię i nazwisko oraz e-mail z Twojego konta zostaną użyte automatycznie (${identity}). Dodaj numer telefonu do tej wiadomości.`],
      [/^(€[\d.,]+) paid$/,(_,amount)=>`Zapłacono: ${amount.replace('.',',')}`],
      [/^Connected and synchronized\. Last update: (.+)\.$/,(_,date)=>`Połączono i zsynchronizowano. Ostatnia aktualizacja: ${dateText(date)}.`],
      [/^Connected, but the last synchronization needs attention: (.+)$/,(_,error)=>`Połączono, ale ostatnia synchronizacja wymaga uwagi: ${copy.get(error)||error}`],
      [/^(Adding|Removing) (.+)\.\.\.$/,(_,action,date)=>`${action==='Adding'?'Dodawanie':'Usuwanie'}: ${dateText(date)}...`],
      [/^Calendar updated: (.+)\.$/,(_,date)=>`Kalendarz zaktualizowany: ${dateText(date)}.`],
      [/^Voice recognition could not continue: (.+)\.$/,(_,error)=>`Nie można kontynuować rozpoznawania mowy: ${error}.`],
      [/^Google Calendar synchronized\. (\d+) Luxia event\(s\) found\.$/,(_,n)=>`Kalendarz Google zsynchronizowany. Liczba znalezionych wydarzeń Luxia: ${n}.`],
      [/^(20 minute consultation|1 hour coaching) with (.+) on (.+)\.$/,(_,label,name,date)=>`${copy.get(label)} — ${name==='the client'?'klient':name}, ${dateText(date)}.`]
    ];
    for (const [pattern,replacement] of patterns) if (pattern.test(key)) return key.replace(pattern,replacement);
    if (new RegExp(`^(${months.join('|')}) \\d{4}$`).test(key) || / · (20-minute consultation|1-hour session)$/.test(key)) return slotText(key);
    const prefixes = [['Hi, ','Cześć, '],['Phone: ','Telefon: '],['Date of birth: ','Data urodzenia: '],['Gender: ','Płeć: '],['Status: ','Status: '],['Payment: ','Płatność: '],['Booking as ','Rezerwujesz jako '],['Request submitted: ','Zgłoszenie wysłane: ']];
    for (const [prefix,replacement] of prefixes) {
      if (!key.startsWith(prefix)) continue;
      let value = key.slice(prefix.length);
      if (prefix === 'Request submitted: ') value = translate(value);
      else if (prefix === 'Date of birth: ' && /^\d{4}-\d{2}-\d{2}$/.test(value)) value = value.split('-').reverse().join('.');
      else if (prefix === 'Booking as ') value = value.replace('verified account','zweryfikowane konto').replace('Phone number unavailable','numer telefonu niedostępny');
      else value = copy.get(value) || value;
      return replacement + value;
    }
    return source;
  }
  function validation(input) {
    const v = input.validity;
    return v.valueMissing ? 'Uzupełnij to wymagane pole.' : v.typeMismatch ? (input.type === 'email' ? 'Wpisz prawidłowy adres e-mail.' : 'Wpisz prawidłową wartość.') : v.tooShort ? `Minimalna liczba znaków: ${input.minLength}.` : v.patternMismatch ? 'Użyj wymaganego formatu.' : v.rangeUnderflow || v.rangeOverflow ? 'Wybierz wartość z dozwolonego zakresu.' : 'Sprawdź wpisaną wartość.';
  }
  return {translate, validation};
})();
